package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.blocks.*;
import com.vandorlabs.tiles.*;
import com.vandorlabs.redstone.*;
import net.minecraft.block.Block;
import net.minecraft.nbt.*;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
/** Real Source row-bank range/local edits preserve live levels and absolute pulse deadlines. */
public final class ScreenTransmissionActionsLegacyChecks {
 private static final int[] CHANNELS={73161,73162,73163,74104};private static final BlockPos POS=new BlockPos(0,80,0);
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();JsonArray cases=new JsonArray();for(String id:ScreenFamilyLegacyChecks.IDS){BlockAnimatedScreenSelector block=null;for(Block candidate:ModBlocks.BLOCKS)if(candidate.getRegistryName().getResourcePath().equals(id))block=(BlockAnimatedScreenSelector)candidate;NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);world.time=100;world.setBlockState(POS,block.getDefaultState(),2);TileEntityAnimatedScreenSelector tile=(TileEntityAnimatedScreenSelector)world.getTileEntity(POS);RedstoneScreenContents controls=tile.redstoneScreen(0);if(!controls.applyRowConfiguration("Bank",ScreenRowActionsLegacyChecks.rows(2,13)))throw new AssertionError("Source transmission rows");controls.toggleRow(1);controls.pulseRow(0);controls.selectSegment(2,2);cases.add(sample(id,0,world,tile));TransmitterSlots.configure(tile,ChannelList.of(74104),256,true);cases.add(sample(id,1,world,tile));world.time=105;TransmitterSlots.configure(tile,ChannelList.EMPTY,4,true);cases.add(sample(id,2,world,tile));world.time=110;TransmitterSlots.configure(tile,ChannelList.EMPTY,16,false);cases.add(sample(id,3,world,tile));world.time=121;controls.expirePulses(121);cases.add(sample(id,4,world,tile));NBTTagCompound saved=controls.writeToNBT(new NBTTagCompound());controls.onChunkUnload();cases.add(sample(id,5,world,tile));controls.readFromNBT(saved);controls.finishLoading();cases.add(sample(id,6,world,tile));controls.invalidate();RedstoneChannels.unregister(tile);}String text=cases.toString();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");StringBuilder digest=new StringBuilder();for(byte b:hash.digest(text.getBytes("UTF-8")))digest.append(String.format("%02x",b&255));if(cases.size()!=49||!digest.toString().equals("1ed5909db77f5af4f037d08caa29afdb1c345ae586105fca934c7c4308fe2d8a"))throw new AssertionError("Source transmission actions changed: "+digest);JsonObject root=new JsonObject();root.addProperty("sha256",digest.toString());root.add("cases",cases);java.nio.file.Path path=java.nio.file.Paths.get("build/test-artifacts/screen-transmission-actions-reference.json");java.nio.file.Files.createDirectories(path.getParent());java.nio.file.Files.write(path,root.toString().getBytes("UTF-8"));System.out.println("Actual Screen transmission actions reference PASS snapshots="+cases.size()+" sha256="+digest);}
 private static JsonObject sample(String id,int phase,NonRenderingChecks.MemoryWorld world,TileEntityAnimatedScreenSelector tile){JsonObject row=new JsonObject();row.addProperty("id",id);row.addProperty("phase",phase);row.addProperty("controls",tile.redstoneScreen(0).writeToNBT(new NBTTagCompound()).toString());row.addProperty("range",TransmitterSlots.range(tile));row.addProperty("local",TransmitterSlots.localRedstone(tile));row.addProperty("channels",TransmitterSlots.channels(tile).toString());row.addProperty("weak",tile.getBlockType().getWeakPower(world.getBlockState(POS),world,POS,EnumFacing.UP));JsonArray near=new JsonArray(),far=new JsonArray();for(int channel:CHANNELS){near.add(RedstoneChannels.level(world,POS,channel));far.add(RedstoneChannels.level(world,POS.east(8),channel));}row.add("near",near);row.add("far",far);return row;}
}
